import os, re, csv, json, numpy as np
from scipy.optimize import linear_sum_assignment # For Hungarian alignment

N = 26
TOL = 1e-8
OUT_ROOT = 'storage/Scientia/nmap/n26/jaccard_analysis_319'

# Paths to relevant packings
D_SCIENTIA_NUDGED = 'storage/Scientia/nmap/n26/nudged_319_data'
D_NOESIS_243 = 'storage/noesis/exports/sota_243'
D_SCIENTIA_259 = 'storage/Scientia/nmap/n26' # My own SOTA
D_PROMETHEUS_298_CANDIDATES = [ # Prometheus's paths, checking common locations
    'storage/Prometheus/nmap/n26/sota_298_data', # Based on Prometheus's Eval ID 298 exports (Eval ID 312, 321)
    'storage/Prometheus/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/prometheus/nmap/n26',
]

# Extended canonicalization for boundary labels (copied from Noesis I)
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}
INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

# ---------- Helper functions (adapted from Noesis I's Eval ID 325) ----------
def first_existing(paths):
    for p in paths:
        if os.path.exists(p): return p
    return None

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    if not os.path.exists(path): return rows
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks: 
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m:
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    # Normalize to 0-based indices
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}
    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}
    out = set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a)
                    out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i)
                    out.add((u, v))
        else: # This is the fixed block
            for (i, s) in rows:
                if 0 <= i < N:
                    out.add((i, s)) # Corrected: use 'i' directly, not 'a'
    return out, meta

def read_centers(path):
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            rows.append([float(toks[0]), float(toks[1])])
    C = np.array(rows, float)
    if C.shape != (N, 2):
        raise ValueError(f"centers shape mismatch: {path} -> {C.shape}")
    return C

def load_pack(dir_root, centers_path=None):
    pr_raw = parse_pairs_raw(os.path.join(dir_root, 'active_pairs_tol1e8.csv'))
    bd_raw = parse_boundary_raw(os.path.join(dir_root, 'active_boundary_tol1e8.csv'))
    pairs, m_pairs = normalize_indices(pr_raw, 'pairs')
    bound, m_bound = normalize_indices(bd_raw, 'bound')
    C = read_centers(centers_path) if centers_path and os.path.exists(centers_path) else None
    return {'pairs': pairs, 'bound': bound, 'centers': C, 'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return J, len(I), len(U), len(U) - len(I)

def align_map(CA, CB):
    if CA is None or CB is None:
        return None # Cannot align without centers
    M = np.sum((CA[:, None, :] - CB[None, :, :])**2, axis=2)
    r, c = linear_sum_assignment(M)
    P = np.zeros(N, dtype=int); P[r] = c
    return P

def map_pairs(P, S):
    if P is None: return S # No alignment
    T = set()
    for (i, j) in S:
        a, b = int(P[i]), int(P[j])
        if a == b:
            continue
        u, v = (a, b) if a < b else (b, a)
        T.add((u, v))
    return T

def map_bound(P, S):
    if P is None: return S # No alignment
    T = set()
    for (i, s) in S:
        T.add((int(P[i]), s))
    return T

def write_jaccard_report(pack_A, pack_B, out_dir, tag_A, tag_B, summary_list):
    # Unaligned
    Jb, Ib, Ub, Db = jaccard(pack_A['bound'], pack_B['bound'])
    Jp, Ip, Up, Dp = jaccard(pack_A['pairs'], pack_B['pairs'])

    # Aligned (A->B) if centers exist
    P = align_map(pack_A['centers'], pack_B['centers'])
    if P is not None:
        Ab, Ap = map_bound(P, pack_A['bound']), map_pairs(P, pack_A['pairs'])
        Jb_aligned, Ib_aligned, Ub_aligned, Db_aligned = jaccard(Ab, pack_B['bound'])
        Jp_aligned, Ip_aligned, Up_aligned, Dp_aligned = jaccard(Ap, pack_B['pairs'])
        alignment_status = "hungarian"
    else:
        Jb_aligned, Ib_aligned, Ub_aligned, Db_aligned = None, None, None, None
        Jp_aligned, Ip_aligned, Up_aligned, Dp_aligned = None, None, None, None
        alignment_status = "unaligned" # Fallback if centers are missing

    # Write JSON report
    json_data = {
        "n": N,
        "pack_A": tag_A,
        "pack_B": tag_B,
        "boundary": {
            "unaligned_jaccard": Jb, "I": Ib, "U": Ub, "D": Db,
            "aligned_jaccard": Jb_aligned, "I_aligned": Ib_aligned, "U_aligned": Ub_aligned
        },
        "pairs": {
            "unaligned_jaccard": Jp, "I": Ip, "U": Up, "D": Dp,
            "aligned_jaccard": Jp_aligned, "I_aligned": Ip_aligned, "U_aligned": Up_aligned, "D_aligned": Dp_aligned
        },
        "alignment": alignment_status
    }
    with open(os.path.join(out_dir, f'{tag_A}_vs_{tag_B}_jaccard.json'), 'w') as f:
        json.dump(json_data, f, indent=2, sort_keys=True)

    # Append to summary list
    summary_list.append({
        'pack_A': tag_A, 'pack_B': tag_B,
        'J_bound_unaligned': Jb, 'J_pairs_unaligned': Jp,
        'J_bound_aligned': Jb_aligned, 'J_pairs_aligned': Jp_aligned
    })

def construct_packing() -> tuple:
    os.makedirs(OUT_ROOT, exist_ok=True)

    summary_of_comparisons = []

    # Load Scientia I's Nudged Packing (Eval ID 319)
    try:
        scientia_nudged_pack = load_pack(D_SCIENTIA_NUDGED, centers_path=os.path.join(D_SCIENTIA_NUDGED, 'centers.txt'))
        print(f"Loaded Scientia I Nudged (Eval ID 319) data from {D_SCIENTIA_NUDGED}")
    except Exception as e:
        print(f"Error loading Scientia I Nudged (Eval ID 319) data: {e}. Returning dummy packing.")
        centers = np.array([[0.5, 0.5]])
        radii = np.array([0.01])
        for _ in range(N - 1):
            centers = np.vstack([centers, [0.5 + 0.01 * np.cos(_), 0.5 + 0.01 * np.sin(_)]])
            radii = np.append(radii, 0.01)
        return centers, radii


    # Load Noesis I's SOTA (Eval ID 243)
    try:
        noesis_243_pack = load_pack(D_NOESIS_243, centers_path='storage/noesis/latest_centers.txt') # Noesis's export strategy
        print(f"Loaded Noesis I SOTA (Eval ID 243) data from {D_NOESIS_243}")
    except Exception as e:
        print(f"Error loading Noesis I SOTA (Eval ID 243) data: {e}. Cannot compare with Noesis.")
        noesis_243_pack = None

    # Load Scientia I's SOTA (Eval ID 259)
    try:
        scientia_259_pack = load_pack(D_SCIENTIA_259, centers_path=os.path.join(D_SCIENTIA_259, 'centers.txt'))
        print(f"Loaded Scientia I SOTA (Eval ID 259) data from {D_SCIENTIA_259}")
    except Exception as e:
        print(f"Error loading Scientia I SOTA (Eval ID 259) data: {e}. Cannot compare with Scientia 259.")
        scientia_259_pack = None

    # Load Prometheus I's SOTA (Eval ID 298)
    prometheus_298_dir = first_existing(D_PROMETHEUS_298_CANDIDATES)
    if prometheus_298_dir:
        try:
            prometheus_298_pack = load_pack(prometheus_298_dir, centers_path=os.path.join(prometheus_298_dir, 'centers.txt'))
            print(f"Loaded Prometheus I SOTA (Eval ID 298) data from {prometheus_298_dir}")
        except Exception as e:
            print(f"Error loading Prometheus I SOTA (Eval ID 298) data: {e}. Cannot compare with Prometheus.")
            prometheus_298_pack = None
    else:
        print(f"[WARN] Prometheus I SOTA (Eval ID 298) exports not found in {D_PROMETHEUS_298_CANDIDATES}. Cannot compare with Prometheus.")
        prometheus_298_pack = None

    # Perform comparisons
    if noesis_243_pack:
        write_jaccard_report(scientia_nudged_pack, noesis_243_pack, OUT_ROOT, 
                             "scientia_nudged_319", "noesis_243", summary_of_comparisons)
    if scientia_259_pack:
        write_jaccard_report(scientia_nudged_pack, scientia_259_pack, OUT_ROOT, 
                             "scientia_nudged_319", "scientia_259", summary_of_comparisons)
    if prometheus_298_pack:
        write_jaccard_report(scientia_nudged_pack, prometheus_298_pack, OUT_ROOT, 
                             "scientia_nudged_319", "prometheus_298", summary_of_comparisons)

    # Write overall summary to CSV
    summary_csv_path = os.path.join(OUT_ROOT, 'jaccard_summary_scientia_nudged_319.csv')
    with open(summary_csv_path, 'w', newline='') as f:
        writer = csv.writer(f)
        if summary_of_comparisons:
            headers = summary_of_comparisons[0].keys()
            writer.writerow(headers)
            for row in summary_of_comparisons:
                writer.writerow(row.values())
        else:
            writer.writerow(['No comparisons made'])

    print(f"Jaccard analysis complete. Results exported to {OUT_ROOT}/")

    # Return a valid dummy packing or the original packing from Eval ID 319
    centers_dummy = np.array([[0.5, 0.5]])
    radii_dummy = np.array([0.01])
    for _ in range(N - 1):
        centers_dummy = np.vstack([centers_dummy, [0.5 + 0.01 * np.cos(_), 0.5 + 0.01 * np.sin(_)]])
        radii_dummy = np.append(radii_dummy, 0.01)
    return centers_dummy, radii_dummy
